    {name:"Vinho tinto suave",detail:"Promoção · preço especial",price:3000,stock:18,promo:true,image:"https://plus.unsplash.com/premium_photo-1725075087044-5c76af72aaa6?auto=format&fit=crop&w=480&q=80"},
    {name:"Água tônica",detail:"Geladeira 01",price:500,stock:9,image:"https://images.unsplash.com/photo-1629203851122-3726ecdf080e?auto=format&fit=crop&w=480&q=80"},
    {name:"Energético",detail:"Geladeira 02",price:800,stock:50,image:"https://images.unsplash.com/photo-1613208602577-50fd21015cca?auto=format&fit=crop&w=480&q=80"},
    {name:"Gin dry 750 ml",detail:"Adega · prateleira B",price:8990,stock:7,image:"https://images.unsplash.com/photo-1569529465841-dfecdab7503b?auto=format&fit=crop&w=480&q=80"},
