  let total=$derived(cart.reduce((a,p)=>a+p.price,0)); const brl=(n:number)=>new Intl.NumberFormat("pt-BR",{style:"currency",currency:"BRL"}).format(n/100);
  onMount(()=>{const carousel=document.querySelector<HTMLElement>(".pos2 .products");if(!carousel)return;const wheel=(event:WheelEvent)=>{if(Math.abs(event.deltaY)<=Math.abs(event.deltaX))return;event.preventDefault();carousel.scrollBy({left:event.deltaY,behavior:"smooth"})};carousel.addEventListener("wheel",wheel,{passive:false});return()=>carousel.removeEventListener("wheel",wheel)});
